mapper.select:
SELECT a.*, u.username, u.nickname, c.name as category_name FROM article a LEFT JOIN user u ON a.user_id = u.id LEFT JOIN category c ON a.category_id = c.id WHERE 1=1
AND a.category_id = #{categoryId}
ORDER BY a.create_time DESC

mapper.update:
UPDATE article
title = #{title}, content = #{content}, summary = #{summary}, category_id = #{categoryId}, update_time = #{updateTime}
WHERE id = #{id}
